"""Exact short vectors in the integral lattice generated by H=T P.

H^t H=7R, Gamma H=-4H. If an integral -4 eigenvector has a coordinate m,
its neighbours sum to -4m and its other coordinates sum to 3m. Thus its
squared norm is at least m^2+7|m|. In particular R-norm 2 allows only
0,+1,-1, and R-norm 4 only 0,+1,-1,+2,-2 at every vertex.

For R-norm 2 there are seven +1 and seven -1 entries. Equal-sign vertices
cannot be adjacent: each would have at least five opposite-sign neighbours,
giving at least three common neighbours. Consequently the support induces
a 4-regular bipartite 2-(7,4,2) incidence graph.

Every pair of equal-sign vertices already has its two common neighbours
in the opposite sign set. It cannot share a root label as well. Since
seven positive (and seven negative) vertices each carry two labels, each
sign set is a perfect matching on the fourteen root-neighbour labels.

No graph is assumed to exist here. These are necessary conditions only.

Integer overlap bound: let N=||h||^2, and h_u,h_v have the same sign with
absolute values r,s. Write e for adjacency and c for shared root labels.
Then r^2+s^2+7(r+s)+2e(r+s+1)+2c <= N+4.
Indeed the two negative neighbour weights total at least (4+e)(r+s).
Their union weighs at most S=sum(h_+), and their intersection has at most
2-c-e vertices. Since t-1 <= t(t-1)/2 for positive integers t, their total
is at most N/2 - [r(r-1)+s(s-1)]/2 + 2-c-e.
For N=28, each sign has at most one coordinate of absolute value two,
and that vertex has no adjacent vertex of the same sign.
"""

from itertools import product
from math import isqrt, lcm

import sympy as sp
from sympy.matrices.normalforms import hermite_normal_form


def short_directions(matrix, maximum_norm=4):
    """Enumerate ALL lattice directions of norm <= maximum_norm, up to sign.

The columns of P=R[anchors,:] generate the lattice in inner-product
coordinates. Column Hermite normal form gives a Z-basis of precisely that
lattice. Its Gram is B^t S^-1 B. This includes short integral combinations
which an arbitrarily bounded search in the original columns could miss.
"""
    matrix = sp.Matrix(matrix)
    anchors = list(matrix.rref()[1])
    if not anchors:
        return {"anchors": [], "directions": [], "lattice_gram": [], "enumeration_box": []}
    small_inverse = matrix.extract(anchors, anchors).inv()
    basis = hermite_normal_form(matrix.extract(anchors, range(matrix.cols)))
    lattice_gram = basis.T * small_inverse * basis
    assert all(x.q == 1 for x in lattice_gram)
    assert all(lattice_gram[i, i] % 2 == 0 for i in range(len(anchors)))
    coordinate_map = basis.T * small_inverse
    inverse = lattice_gram.inv()
    bounds = [isqrt(int((maximum_norm * inverse[i, i]).p) //
                    int((maximum_norm * inverse[i, i]).q)) for i in range(len(anchors))]
    gram = [[int(x) for x in row] for row in lattice_gram.tolist()]
    directions = []
    for z in product(*(range(-b, b + 1) for b in bounds)):
        if not any(z) or next(x for x in z if x) < 0:
            continue
        norm = sum(z[i] * gram[i][j] * z[j] for i in range(len(z)) for j in range(len(z)))
        if not 0 < norm <= maximum_norm:
            continue
        evaluation = sp.Matrix([z]) * coordinate_map
        denominator = lcm(*(int(x.q) for x in evaluation))
        numerator = [int(x * denominator) for x in evaluation]
        maximum_coordinate = (isqrt(49 + 28 * norm) - 7) // 2
        directions.append({"norm": norm, "lattice_coefficients": list(z),
                           "numerator": numerator, "denominator": denominator,
                           "maximum_coordinate": maximum_coordinate})
    return {"anchors": anchors, "directions": directions, "lattice_gram": gram,
            "enumeration_box": bounds, "complete_through_norm": maximum_norm}


def evaluations(signature, data, roots_only=False):
    coordinates = [signature[a] for a in data["anchors"]]
    values = []
    for direction in data["directions"]:
        if roots_only and direction["norm"] != 2:
            continue
        numerator = sum(a * b for a, b in zip(coordinates, direction["numerator"]))
        denominator = direction["denominator"]
        assert numerator % denominator == 0, "Lattice basis evaluation must be integral."
        values.append(numerator // denominator)
    return tuple(values)


def norm4_overlap_masks(signature, data):
    """Bitmasks +2, -2, positive and negative on the norm-four directions."""
    values=[v for v,d in zip(evaluations(signature,data),data['directions']) if d['norm']==4]
    return tuple(sum(1<<i for i,v in enumerate(values) if predicate(v)) for predicate in
                 (lambda v:v==2,lambda v:v==-2,lambda v:v>0,lambda v:v<0))


def norm4_pair_admissible(a,b,edge):
    if a[0]&b[0] or a[1]&b[1]:return False
    return not edge or not (a[0]&b[2] or b[0]&a[2] or a[1]&b[3] or b[1]&a[3])


def integer_pair_margins(a, b, lattice_norms):
    """Maximum allowed twice-shared-label count for nonedge/edge respectively."""
    margins=[10**9,10**9]
    for x,y,norm in zip(a,b,lattice_norms):
        if x*y<=0:continue
        r,s=abs(x),abs(y)
        free=7*norm+4-r*r-s*s-7*(r+s)
        margins[0]=min(margins[0],free)
        margins[1]=min(margins[1],free-2*(r+s+1))
    return tuple(margins)


def add_integer_overlap_counts(model, data, terms):
    """Aggregate overlap bounds for any enumerated integral directions.

For two positive entries >=r, negative-neighbour overlap also gives
E_+ <= N/2+2-8r, where E_+=sum h_+(h_+-1)/2 over ALL coordinates.
Thus the number of entries >=r is at most max(1,floor((N/2+2-8r)/binom(r,2))).
The same conclusions hold for the negative sign. Terms may be individual
signature indicators or integer multiplicities, so this works in both models.
    """
    buckets=[{} for _ in data['directions']]
    for signature,variable in terms:
        for bucket,value in zip(buckets,evaluations(signature,data)):
            if abs(value)>=2:bucket.setdefault(value,[]).append(variable)
    constraints=0;directions_used=0
    for di,(direction,bucket) in enumerate(zip(data['directions'],buckets)):
        if not bucket:continue
        directions_used+=1
        norm=7*direction['norm'];maximum=direction['maximum_coordinate']
        assert norm%2==0
        for sign in (-1,1):
            counts={r:sum(bucket.get(sign*r,[])) for r in range(2,maximum+1)}
            excess=sum(r*(r-1)//2*count for r,count in counts.items())
            caps={}
            for r in counts:
                if not any(sign*s in bucket for s in range(r,maximum+1)):continue
                above=sum(counts[s] for s in range(r,maximum+1))
                upper=norm//2+2-8*r
                cap=max(1,upper//(r*(r-1)//2));caps[r]=cap
                model.add(above<=cap);constraints+=1
                if cap>=2:
                    repeated=model.new_bool_var(f'integer_overlap_repeat_{di}_{sign}_{r}')
                    model.add(above>=2).only_enforce_if(repeated)
                    model.add(above<=1).only_enforce_if(repeated.Not())
                    model.add(excess<=upper).only_enforce_if(repeated)
                    constraints+=3
            for r in range(2,maximum+1):
                for s in range(r+1,maximum+1):
                    if sign*r not in bucket or sign*s not in bucket:continue
                    if r*r+s*s+7*(r+s)>norm+4:
                        assert caps[s]==1
                        model.add(counts[r]+84*counts[s]<=84);constraints+=1
    return {'integer_overlap_directions':directions_used,'integer_overlap_constraints':constraints,
            'maximum_lattice_norm':data.get('complete_through_norm',4)}


def admissible(signature, data):
    return all(abs(v) <= d["maximum_coordinate"]
               for v, d in zip(evaluations(signature, data), data["directions"]))


def add_short_triangle_cuts(model, triangles, data, signatures, indicators):
    """No strict same-sign triangle for an integral -4 vector of norm28.

For any line L, sum_{N(L)} h = -6 sum_L h, since each exterior
neighbour meets L exactly once. A strict same-sign triangle has absolute
sum at least3, hence opposite-sign mass at least18. But integral h with
norm28 and sum0 has each sign mass at most14. This proves the exclusion.
The argument does not use an assumed automorphism or a selected witness.
    """
    selected=[i for i,d in enumerate(data['directions']) if d['norm']==4]
    cache={}
    def values(h):
        key=tuple(h)
        if key not in cache:cache[key]=evaluations(h,data)
        return cache[key]
    clauses=0;auxiliary=0;forced_absent=0
    for di in selected:
        for sign in (-1,1):
            flags=[]
            for w,rows in enumerate(signatures):
                active=[i for i,h in enumerate(rows) if sign*values(h)[di]>0]
                if not active:flag=0
                elif len(active)==len(rows):flag=1
                else:
                    flag=model.new_bool_var(f'short_triangle_sign_{di}_{sign}_{w}')
                    model.add(flag==sum(indicators[w][i] for i in active));auxiliary+=1
                flags.append(flag)
            for vertices,triangle in triangles:
                fs=[triangle,*[flags[w] for w in vertices]]
                if any(isinstance(f,int) and not f for f in fs):continue
                unknown=[f for f in fs if not isinstance(f,int)]
                model.add_bool_or([f.Not() for f in unknown]);clauses+=1
                if len(unknown)<=1:forced_absent+=1
    mass_equations=0;mass_directions=0;coordinate_variables=0
    for di,direction in enumerate(data['directions']):
        if direction['norm']<6:continue
        norm=7*direction['norm'];maximum=direction['maximum_coordinate']
        mass=model.new_int_var((norm+2*maximum-1)//(2*maximum),norm//2,f'short_line_mass_{di}')
        model.add(mass==sum(max(0,values(h)[di])*flag
            for rows,fs in zip(signatures,indicators) for h,flag in zip(rows,fs)))
        coordinates=[];bounds=[]
        for w,rows in enumerate(signatures):
            vs=[values(h)[di] for h in rows];lo,hi=min(vs),max(vs)
            if lo==hi:value=lo
            else:
                value=model.new_int_var(lo,hi,f'short_line_value_{di}_{w}')
                model.add(value==sum(v*flag for v,flag in zip(vs,indicators[w])))
                coordinate_variables+=1
            coordinates.append(value);bounds.append((lo,hi))
        for vertices,triangle in triangles:
            expression=6*sum(coordinates[w] for w in vertices)
            for sign in (-1,1):
                upper=6*sum(bounds[w][1] if sign==1 else -bounds[w][0] for w in vertices)
                if upper<=(norm+2*maximum-1)//(2*maximum):continue
                constraint=model.add(sign*expression<=mass)
                if not isinstance(triangle,int):constraint.only_enforce_if(triangle)
                elif not triangle:raise AssertionError('Triangle list contains a false constant.')
                mass_equations+=1
        mass_directions+=1
    return {'norm28_directions':len(selected),'sign_indicators':auxiliary,
            'same_sign_triangle_clauses':clauses,'unit_or_empty_clauses':forced_absent,
            'general_line_mass_directions':mass_directions,'general_line_mass_equations':mass_equations,
            'general_line_mass_coordinates':coordinate_variables,
            'scope':add_short_triangle_cuts.__doc__}


def make_rotated_signature_values(model,data,signatures,indicators):
    """Coordinates of short -4 eigenvectors on Gamma; the other15 are zero."""
    norms=[d['norm'] for d in data['directions']]
    values=[[] for _ in norms];bounds=[[] for _ in norms]
    cache={}
    for w,(rows,flags) in enumerate(zip(signatures,indicators)):
        for h in rows:
            key=tuple(h)
            if key not in cache:cache[key]=evaluations(h,data)
        for di in range(len(norms)):
            vs=[cache[tuple(h)][di] for h in rows];lo,hi=min(vs),max(vs)
            if lo==hi:value=lo
            else:
                value=model.new_int_var(lo,hi,f'rotated_signature_h_{di}_{w}')
                model.add(value==sum(v*f for v,f in zip(vs,flags)))
            values[di].append(value);bounds[di].append((lo,hi))
    if data['directions']:
        independent=list(sp.Matrix([d['numerator'] for d in data['directions']]).T.rref()[1])
    else:independent=[]
    return {'values':values,'bounds':bounds,'lattice_norms':norms,'independent_directions':independent}


def add_component_signature_cuts(model,partitions,context):
    """For a component union S of size6s at L, sum_S h+s*sum_L h=0.

Its balanced colours, internal degree3 and constant exterior degree s
give A(1_S+s1_L)=3(1_S+s1_L)+s1. Orthogonality to every -4 eigenvector
proves the identity. Bin membership and the eigenvector remain variables.
Indices in partitions refer to the full99 graph, Gamma has offset15.
"""
    values=context['values'];bounds=context['bounds']
    directions=context['independent_directions'];products=0;equations=0
    for pi,partition in enumerate(partitions):
        for di in directions:
            line_vertices=[w-15 for w in partition['line'] if w>=15]
            lo=sum(bounds[di][w][0] for w in line_vertices)
            hi=sum(bounds[di][w][1] for w in line_vertices)
            if lo==hi:line_sum=lo
            else:
                line_sum=model.new_int_var(lo,hi,f'component_h_line_{pi}_{di}')
                model.add(line_sum==sum(values[di][w] for w in line_vertices))
            for j,half in enumerate(partition['halves'],1):
                terms=[]
                for global_w,flags in partition['flags'].items():
                    if global_w<15:continue
                    w=global_w-15;h=values[di][w];flag=flags[j]
                    if isinstance(h,int):
                        if h:terms.append(h*flag)
                        continue
                    low,high=bounds[di][w]
                    v=model.new_int_var(min(0,low),max(0,high),f'component_h_member_{pi}_{di}_{j}_{w}')
                    model.add(v==h).only_enforce_if(flag)
                    model.add(v==0).only_enforce_if(flag.Not())
                    terms.append(v);products+=1
                if isinstance(line_sum,int):rhs=half*line_sum
                else:
                    rhs=model.new_int_var(min(lo,3*lo),max(hi,3*hi),f'component_h_line_multiple_{pi}_{di}_{j}')
                    model.add_multiplication_equality(rhs,[half,line_sum]);products+=1
                model.add(sum(terms)+rhs==0);equations+=1
    return {'lines':len(partitions),'independent_directions':len(directions),
            'equations':equations,'products':products,'scope':add_component_signature_cuts.__doc__}


def add_rotated_signature_cuts(model,rectangles,context):
    """For each rotated nine-set S, (sum_S h)^2 <= q*(8-2e).

Here h is an integral -4 eigenvector with norm squared7q, and e is the
number of edges among its four rectangle corners. The full projector is
E_-4=(3I-A+J/9)/7. The nine-set has14+e edges, so
1_S^t E_-4 1_S=(8-2e)/7. Cauchy--Schwarz proves the cut.
For e=4 this forces sum_S h=0. Every rectangle root is one of the original
fourteen neighbours, where these h vanish; the four base and four corner
coordinates are in Gamma. Corners remain variable, selected exactly.
"""
    from math import isqrt
    from ortools.sat.python import cp_model
    values=context['values'];bounds=context['bounds'];norms=context['lattice_norms']
    assert all(len(row)==84 for row in values)
    selected={};tables=0;elements=0;entries=0
    for ri,rectangle in enumerate(rectangles):
        assert 0<=rectangle['root']<14
        edge_count=model.new_int_var_from_domain(cp_model.Domain.from_values([0,1,2,4]),f'rotated_signature_edges_{ri}')
        model.add(edge_count==sum(rectangle['edges']))
        for di,q in enumerate(norms):
            terms=[values[di][w] for w in rectangle['base_vertices']]
            for corner in rectangle['corners']:
                key=(di,corner['actual'].index)
                if key not in selected:
                    vs=[values[di][w] for w in corner['choices']]
                    lo=min(bounds[di][w][0] for w in corner['choices'])
                    hi=max(bounds[di][w][1] for w in corner['choices'])
                    if lo==hi:variable=lo
                    else:
                        variable=model.new_int_var(lo,hi,f'rotated_signature_corner_{di}_{corner["actual"].index}')
                        model.add_element(corner['selector'],vs,variable)
                        elements+=1;entries+=len(vs)
                    selected[key]=variable
                terms.append(selected[key])
            cap=isqrt(8*q)
            total=model.new_int_var(-cap,cap,f'rotated_signature_sum_{ri}_{di}')
            model.add(total==sum(terms))
            model.add_allowed_assignments([edge_count,total],
                [(e,s) for e in (0,1,2,4) for s in range(-isqrt(q*(8-2*e)),isqrt(q*(8-2*e))+1)])
            tables+=1
    return {'rectangles':len(rectangles),'directions':len(norms),'tables':tables,
            'selected_coordinates':elements,'element_entries':entries,'scope':add_rotated_signature_cuts.__doc__}


def filter_domains(domains, data):
    before = sum(len(item["signatures"]) for item in domains.values())
    for item in domains.values():
        item["signatures"] = [h for h in item["signatures"] if admissible(h, data)]
    return {"before": before, "after": sum(len(item["signatures"]) for item in domains.values()),
            "norm2_directions": sum(d["norm"] == 2 for d in data["directions"]),
            "norm4_directions": sum(d["norm"] == 4 for d in data["directions"]),
            "lattice_gram": data["lattice_gram"], "enumeration_box": data["enumeration_box"],
            "complete_through_norm": data.get("complete_through_norm", 4)}
